-- MP-0048: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='government' and type='bloc') then raise exception 'MP-0048: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='mca' and type='party') then raise exception 'MP-0048: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('wee-jeck-seng','suhaili-abdul-rahman','verdon-bahanda') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0048: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('tanjung piai','labuan','kudat') and slug not in ('wee-jeck-seng','suhaili-abdul-rahman','verdon-bahanda')) then raise exception 'MP-0048: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0048:%' and (m.source_type <> 'editorial' or e.slug not in ('wee-jeck-seng','suhaili-abdul-rahman','verdon-bahanda') or m.import_key not like 'MP-0048:' || e.slug || ':%')) then raise exception 'MP-0048: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'wee-jeck-seng','Wee Jeck Seng','government','Member of the Dewan Rakyat','Tanjung Piai','Johor','Wee Jeck Seng represents Tanjung Piai, Johor, in the Dewan Rakyat. Affiliated with MCA.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4204','/portraits/wee-jeck-seng.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P165.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4204"}, {"label": "MCA · current vice-president, 20 August 2026", "url": "https://www.thestar.com.my/news/nation/2026/08/20/new-rm1mil-allocation-welcomed"}]'::jsonb from public.entities parent where parent.slug='mca' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'suhaili-abdul-rahman','Suhaili Abdul Rahman','government','Member of the Dewan Rakyat','Labuan','Labuan','Suhaili Abdul Rahman represents Labuan, Labuan, in the Dewan Rakyat. An independent MP supporting the federal government.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4205','/portraits/suhaili-abdul-rahman.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P166.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4205"}, {"label": "Independent government support · CSA, 29 October 2026", "url": "https://www.bernama.com/bm/am/news.php?id=2627381"}]'::jsonb from public.entities parent where parent.slug='government' and parent.type='bloc' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',null,'verdon-bahanda','Verdon Bahanda','independent','Member of the Dewan Rakyat','Kudat','Sabah','Verdon Bahanda represents Kudat, Sabah, in the Dewan Rakyat. Parliament lists him as independent; no party or federal bloc is assigned in this review.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4206','/portraits/verdon-bahanda.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P167.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4206"}, {"label": "Independent status · personal statement, 13 August 2026", "url": "https://www.thestar.com.my/news/nation/2026/08/13/sabahs-bahanda-brothers-eyeing-return-to-bn"}]'::jsonb on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('wee-jeck-seng','suhaili-abdul-rahman','verdon-bahanda') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0048: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0048:suhaili-abdul-rahman:budget-2027-csa','Support Supply Bill 2027 under the confidence-and-supply agreement','Governance',null,null,null,'2026-10-29','https://www.bernama.com/bm/am/news.php?id=2627381',null,null,'Signed the agreement committing support for the 2027 Supply Bill.','The agreement is documented. A subsequent budget vote or final passage was not established in this pass; signing is not counted as delivery of the bill or joining another party.','2026-11-10','editorial',false from public.entities e where e.slug='suhaili-abdul-rahman' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

